{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Tetrabenazine, a ketone-containing benzoquinolizine, has very low oral bioavailability (0.053) in a fasted patient; its low F is driven by rapid first-pass ketone reduction, a liability absent in the query's morphinan ether-bridge scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "A morphinan-like ThH has very low oral bioavailability, but it bears a phenolic OH and N-cyclopropylmethyl substituent that promote first-pass conjugation; the query has a 3-methyl ether and N-methyl, which avoid these specific liabilities.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Morphine-6-glucuronide has poor oral bioavailability due to its polar glucuronide moiety; the query is not a glucuronide and is a lipophilic tertiary amine, so this low-F evidence does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Trospium's low bioavailability is attributed to its quaternary ammonium hydrophilicity and slow gastrointestinal absorption; the query is a non-quaternary tertiary amine with better membrane permeability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is codeine, a morphinan with a 3-methyl ether and N-methyl group; its oral bioavailability is known to be approximately 50%, well above the 20% threshold. The retrieved low-F analogues are not mechanistically transferable because their low F arises from ketone reduction, phenolic conjugation, glucuronide polarity, or quaternary ammonium charge, none of which apply to the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct oral bioavailability record for the query was retrieved.",
    "All retrieved low-F analogues differ in key F-limiting structural features (ketone, phenol, glucuronide, quaternary ammonium) that are absent in the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

